SELECT /*selectSellerMpClClosInfoList*/ S.BUYER_NAME, S.PO_CREATE_DATE, S.BUYER_ITEM_NO, S.PO_NO, S.DESCRIPTION, S.SPECIFICATION, S.AGENT_PRICE, S.UNIT_MEASURE, S.PO_QTY, S.PO_AMT, S.DELIVERY_QTY, S.DELIVERY_AMT, S.GR_QTY, S.GR_AMT, S.DS_DATE, S.DELIVERY_DATE, S.LEGACY_PO_NO, S.LEGACY_PO_SEQ, S.BUYER, S.PO_SEQ, S.BYIT_COMORG_CODE, S.CONTRACT_NO, S.CONTRACT_SEQ, F_GET_HIDDEN_BUYER_NAME(S.BUYER, '01') AS BUYER2, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = S.KEP_USER_ID) AS KEP_USER_NAME, (SELECT PHONE_NUMBER FROM ICOMLUSR WHERE USER_ID = S.KEP_USER_ID) AS KEP_USER_PHONE, S.PURCHASER_NAME, S.CHANGE_USER_MOBILE_PHONE FROM ( SELECT (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = F_GET_HIDDEN_BUYER_NAME(X.BUYER, '01'))|| (SELECT '('||COM_NAME_LOC||')' FROM ICOMCMPY WHERE X.PROCESS_TYPE = '2' AND COM_CODE = DECODE(X.PROCESS_TYPE,'2',X.WAREHOUSE_CODE,X.BUYER)) AS BUYER_NAME, X.PO_CREATE_DATE, X.BUYER_ITEM_NO, X.PO_NO, X.DESCRIPTION, X.SPECIFICATION, X.AGENT_PRICE, X.UNIT_MEASURE, X.PO_QTY, X.PO_AMT, X.DELIVERY_QTY, X.DELIVERY_AMT, X.GR_QTY, X.GR_AMT, X.DS_DATE, X.DELIVERY_DATE, X.LEGACY_PO_NO, X.LEGACY_PO_SEQ, X.BUYER, X.PO_SEQ, X.BYIT_COMORG_CODE, X.CONTRACT_NO, X.CONTRACT_SEQ, X.KEP_USER_ID, X.PURCHASER_NAME, X.CHANGE_USER_MOBILE_PHONE FROM ( SELECT MAX(Z.PO_CREATE_DATE) AS PO_CREATE_DATE, Z.BUYER_ITEM_NO, Z.PO_NO, MAX(Z.DESCRIPTION) AS DESCRIPTION, MAX(Z.SPECIFICATION) AS SPECIFICATION, MAX(Z.AGENT_PRICE) AS AGENT_PRICE, MAX(Z.UNIT_MEASURE) AS UNIT_MEASURE, MAX(NVL(Z.PO_QTY,0)) AS PO_QTY, MAX(NVL(Z.PO_AMT,0)) AS PO_AMT, MAX(NVL(Z.DELIVERY_QTY,0)) AS DELIVERY_QTY, MAX(NVL(Z.DELIVERY_AMT,0)) AS DELIVERY_AMT, MAX(NVL(Z.GR_QTY,0)) AS GR_QTY, MAX(NVL(Z.GR_AMT,0)) AS GR_AMT, MAX(Z.DS_DATE) AS DS_DATE, MAX(Z.DELIVERY_DATE) AS DELIVERY_DATE, MAX(Z.LEGACY_PO_NO) AS LEGACY_PO_NO, MAX(Z.LEGACY_PO_SEQ) AS LEGACY_PO_SEQ, Z.BUYER, Z.PO_SEQ, MAX(Z.BYIT_COMORG_CODE) BYIT_COMORG_CODE, MAX(Z.CONTRACT_NO) CONTRACT_NO, MAX(Z.CONTRACT_SEQ) CONTRACT_SEQ, MAX(NVL(Z.PLANT_USER_ID,(SELECT MAX(MNG.KEP_USER_ID) AS KEP_USER_ID FROM MIS_BUYER_MNG MNG WHERE MNG.YEAR = TO_CHAR(SYSDATE,'YYYY') AND MNG.BUYER = Z.BUYER AND MNG.PRIORITY = 'Y' AND MNG.STATUS <> 'O'))) AS KEP_USER_ID, MAX(Z.PURCHASER_NAME) AS PURCHASER_NAME, MAX(Z.CHANGE_USER_MOBILE_PHONE) AS CHANGE_USER_MOBILE_PHONE, MAX(Z.PROCESS_TYPE) AS PROCESS_TYPE, MAX(Z.WAREHOUSE_CODE) AS WAREHOUSE_CODE FROM ( SELECT MAX(C.PO_CREATE_DATE) PO_CREATE_DATE, B.BUYER_ITEM_NO BUYER_ITEM_NO, B.PO_NO PO_NO, MAX(B.DESCRIPTION) DESCRIPTION, MAX(B.SPECIFICATION) SPECIFICATION, MAX(B.AGENT_PRICE)/F_GET_VATRATE(B.BUYER) AGENT_PRICE, MAX(B.UNIT_MEASURE) UNIT_MEASURE, MAX(B.ITEM_QTY) PO_QTY, MAX(B.AGENT_ITEM_AMT)/F_GET_VATRATE(B.BUYER) PO_AMT, SUM(A.DELIVERY_QTY) DELIVERY_QTY, 0 GR_QTY, MAX(B.AGENT_PRICE)/F_GET_VATRATE(B.BUYER) * SUM(A.DELIVERY_QTY) DELIVERY_AMT, 0 GR_AMT, MAX(A.DS_DATE) DS_DATE, MAX(A.DELIVERY_DATE) DELIVERY_DATE, MAX(B.LEGACY_PO_NO) LEGACY_PO_NO, MAX(B.LEGACY_PO_SEQ) LEGACY_PO_SEQ, B.BUYER, B.PO_SEQ, MAX(B.BYIT_COMORG_CODE) BYIT_COMORG_CODE, MAX(B.CONTRACT_NO) CONTRACT_NO, MAX(B.CONTRACT_SEQ) CONTRACT_SEQ, MAX(C.PURCHASER_NAME) AS PURCHASER_NAME, '' AS CHANGE_USER_MOBILE_PHONE, MAX(C.PROCESS_TYPE) AS PROCESS_TYPE, MAX(B.WAREHOUSE_CODE) AS WAREHOUSE_CODE, MAX((SELECT MAX(COD3.CODE1) AS PLANT_USER_ID FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'ISMG' AND PR.PURCHASER_DEPT = COD3.CODE2 AND PR.BUYER = COD3.BUYER)) AS PLANT_USER_ID FROM ICOMIVDT A, ICOMPODT B , ICOMPOHD C, KEP_AGENT_BUYER G, ICOMPRDT PR WHERE NVL(A.DELIVERY_QTY,0) > 0 AND A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND A.PO_SEQ = B.PO_SEQ AND A.BUYER = C.BUYER AND A.PO_NO = C.PO_NO AND B.BUYER = PR.BUYER AND B.PR_NO = PR.PR_NO AND B.PR_SEQ = PR.PR_SEQ AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND PR.STATUS <> 'D' AND C.AGENT = #{st_com_code} AND A.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND G.AGENT = C.AGENT AND G.BUYER = C.BUYER AND G.BUYER = A.BUYER
AND C.BUYER = #{st_buyer_code}
GROUP BY B.BUYER, B.PO_NO, B.PO_SEQ, B.BUYER_ITEM_NO
UNION ALL
SELECT MAX(C.PO_CREATE_DATE) PO_CREATE_DATE, B.BUYER_ITEM_NO BUYER_ITEM_NO, B.PO_NO PO_NO, MAX(B.DESCRIPTION) DESCRIPTION, MAX(B.SPECIFICATION) SPECIFICATION, MAX(B.AGENT_PRICE)/F_GET_VATRATE(B.BUYER) AGENT_PRICE, MAX(B.UNIT_MEASURE) UNIT_MEASURE, MAX(B.ITEM_QTY) PO_QTY, MAX(B.AGENT_ITEM_AMT)/F_GET_VATRATE(B.BUYER) PO_AMT, SUM(A.DELIVERY_QTY) DELIVERY_QTY, 0 GR_QTY, MAX(B.AGENT_PRICE)/F_GET_VATRATE(B.BUYER) * SUM(A.DELIVERY_QTY) DELIVERY_AMT, 0 GR_AMT, MAX(B.RD_DATE) DS_DATE, MAX(A.DELIVERY_DATE) DELIVERY_DATE, MAX(B.LEGACY_PO_NO) LEGACY_PO_NO, MAX(B.LEGACY_PO_SEQ) LEGACY_PO_SEQ, B.BUYER, B.PO_SEQ, MAX(B.BYIT_COMORG_CODE) BYIT_COMORG_CODE, MAX(B.CONTRACT_NO) CONTRACT_NO, MAX(B.CONTRACT_SEQ) CONTRACT_SEQ, MAX(C.PURCHASER_NAME) AS PURCHASER_NAME, '' AS CHANGE_USER_MOBILE_PHONE, MAX(C.PROCESS_TYPE) AS PROCESS_TYPE, MAX(B.WAREHOUSE_CODE) AS WAREHOUSE_CODE, MAX((SELECT MAX(COD3.CODE1) AS PLANT_USER_ID FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'ISMG' AND PR.PURCHASER_DEPT = COD3.CODE2 AND PR.BUYER = COD3.BUYER)) AS PLANT_USER_ID FROM WMSIVDT A, ICOMPODT B , ICOMPOHD C, KEP_AGENT_BUYER G, ICOMPRDT PR WHERE NVL(A.DELIVERY_QTY,0) > 0 AND A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND A.PO_SEQ = B.PO_SEQ AND A.BUYER = C.BUYER AND A.PO_NO = C.PO_NO AND B.BUYER = PR.BUYER AND B.PR_NO = PR.PR_NO AND B.PR_SEQ = PR.PR_SEQ AND A.BUYER = G.BUYER AND C.AGENT = G.AGENT AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND PR.STATUS <> 'D' AND B.WAREHOUSE_CODE = #{st_com_code} AND A.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND B.PROCESS_TYPE = '3'
AND C.BUYER = #{st_buyer_code}
GROUP BY B.BUYER, B.PO_NO, B.PO_SEQ, B.BUYER_ITEM_NO
UNION ALL
SELECT MAX(C.PO_CREATE_DATE) PO_CREATE_DATE, B.BUYER_ITEM_NO BUYER_ITEM_NO, B.PO_NO PO_NO, MAX(B.DESCRIPTION) DESCRIPTION, MAX(B.SPECIFICATION) SPECIFICATION, MAX(B.AGENT_PRICE)/F_GET_VATRATE(B.BUYER) AGENT_PRICE, MAX(B.UNIT_MEASURE) UNIT_MEASURE, MAX(B.ITEM_QTY) PO_QTY, MAX(B.AGENT_ITEM_AMT)/F_GET_VATRATE(B.BUYER) PO_AMT, 0 DELIVERY_QTY, SUM(A.ITEM_QTY) GR_QTY, 0 DELIVERY_AMT, MAX(A.AGENT_PRICE)/F_GET_VATRATE(B.BUYER) * SUM(A.ITEM_QTY) GR_AMT, NULL DS_DATE, NULL DELIVERY_DATE, MAX(B.LEGACY_PO_NO) LEGACY_PO_NO, MAX(B.LEGACY_PO_SEQ) LEGACY_PO_SEQ, B.BUYER, B.PO_SEQ, MAX(B.BYIT_COMORG_CODE) BYIT_COMORG_CODE, MAX(B.CONTRACT_NO) CONTRACT_NO, MAX(B.CONTRACT_SEQ) CONTRACT_SEQ, MAX(C.PURCHASER_NAME) AS PURCHASER_NAME, '' AS CHANGE_USER_MOBILE_PHONE, MAX(C.PROCESS_TYPE) AS PROCESS_TYPE, MAX(B.WAREHOUSE_CODE) AS WAREHOUSE_CODE, MAX((SELECT MAX(COD3.CODE1) AS PLANT_USER_ID FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'ISMG' AND PR.PURCHASER_DEPT = COD3.CODE2 AND PR.BUYER = COD3.BUYER)) AS PLANT_USER_ID FROM ICOMGRDT A, ICOMPODT B, ICOMPOHD C, KEP_AGENT_BUYER G, ICOMPRDT PR WHERE A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND A.PO_SEQ = B.PO_SEQ AND A.BUYER = C.BUYER AND A.PO_NO = C.PO_NO AND B.BUYER = PR.BUYER AND B.PR_NO = PR.PR_NO AND B.PR_SEQ = PR.PR_SEQ AND A.BUYER = G.BUYER AND C.AGENT = G.AGENT AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND PR.STATUS <> 'D' AND C.AGENT = #{st_com_code} AND A.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND C.BUYER = #{st_buyer_code}
AND A.AP_BILL_FLAG = #{st_ap_yn}
GROUP BY B.BUYER, B.PO_NO, B.PO_SEQ, B.BUYER_ITEM_NO
UNION ALL
SELECT MAX(C.PO_CREATE_DATE) PO_CREATE_DATE, B.BUYER_ITEM_NO BUYER_ITEM_NO, B.PO_NO PO_NO, MAX(B.DESCRIPTION) DESCRIPTION, MAX(B.SPECIFICATION) SPECIFICATION, MAX(B.AGENT_PRICE)/F_GET_VATRATE(B.BUYER) AGENT_PRICE, MAX(B.UNIT_MEASURE) UNIT_MEASURE, MAX(B.ITEM_QTY) PO_QTY, MAX(B.AGENT_ITEM_AMT)/F_GET_VATRATE(B.BUYER) PO_AMT, 0 DELIVERY_QTY, SUM(A.ITEM_QTY) GR_QTY, 0 DELIVERY_AMT, MAX(A.AGENT_PRICE)/F_GET_VATRATE(B.BUYER) * SUM(A.ITEM_QTY) GR_AMT, NULL DS_DATE, NULL DELIVERY_DATE, MAX(B.LEGACY_PO_NO) LEGACY_PO_NO, MAX(B.LEGACY_PO_SEQ) LEGACY_PO_SEQ, B.BUYER, B.PO_SEQ, MAX(B.BYIT_COMORG_CODE) BYIT_COMORG_CODE, MAX(B.CONTRACT_NO) CONTRACT_NO, MAX(B.CONTRACT_SEQ) CONTRACT_SEQ, MAX(C.PURCHASER_NAME) AS PURCHASER_NAME, '' AS CHANGE_USER_MOBILE_PHONE, MAX(C.PROCESS_TYPE) AS PROCESS_TYPE, MAX(B.WAREHOUSE_CODE) AS WAREHOUSE_CODE, MAX((SELECT MAX(COD3.CODE1) AS PLANT_USER_ID FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'ISMG' AND PR.PURCHASER_DEPT = COD3.CODE2 AND PR.BUYER = COD3.BUYER)) AS PLANT_USER_ID FROM ICOMGRDT A, ICOMPODT B, ICOMPOHD C, KEP_AGENT_BUYER G, ICOMPRDT PR WHERE A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND A.PO_SEQ = B.PO_SEQ AND A.BUYER = C.BUYER AND A.PO_NO = C.PO_NO AND B.BUYER = PR.BUYER AND B.PR_NO = PR.PR_NO AND B.PR_SEQ = PR.PR_SEQ AND C.AGENT = G.AGENT AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND PR.STATUS <> 'D' AND B.WAREHOUSE_CODE = #{st_com_code} AND A.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND B.PROCESS_TYPE = '3' AND G.BUYER = B.BUYER AND G.BUYER = A.BUYER
